// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd = $getWorkflowStaticData('global');
let launch = null;
try { const r = $('Fetch Launch Record').first().json; if (r && r.id) launch = r; } catch (e) {}
const f = (launch && launch.fields) || launch || {};
const cl = Array.isArray(f.Client) && f.Client.length ? f.Client[0] : '';
const clientFilter = (cl && typeof cl === 'object') ? String(cl.id || '') : String(cl || '');
sd.launch = { recordId: launch ? String(launch.id) : '', trigger: launch ? 'form' : 'schedule', clientFilter, startedAt: $now.toMillis() };
sd.results = []; sd.updates = []; sd.feeds = []; sd.failed = []; sd.syncs = []; sd.updated = 0; sd.fed = 0; sd.abort = '';
return [{ json: Object.assign({}, sd.launch) }];

// Decide: the standard, applied once over every campaign that carries a Stage.
// Reads only what the Hub already holds: the Campaigns rows, which the three syncs wrote minutes
// ago at the top of this run and the deploy doors stamp with Left in View and Last Fed. Never a
// platform.
// Writes nothing here: it plans the Stage moves (Test to Scale, Test to Killed, never Run) and
// the per-client report blocks into static data; Update Stage and Build Messages consume them.
// The numbers below are the card's standard block (managers/Campaigns-Manager/card.json); a change
// there is a change here, in the same commit.
const STANDARD = {
  stageTotal: { Test: 1000, Scale: 3000, Run: null },
  line: { Test: 1000, Scale: 3000 },
  positives: { Email: 1, LinkedIn: 3 },
  inPlayStages: ['Test', 'Scale', 'Run'],
  notInPlayStatus: ['PAUSED', 'DRAFT', 'STOPPED'],
};
const sd = $getWorkflowStaticData('global');
const launch = sd.launch || {};
const cf = String(launch.clientFilter || '');
const nm = v => (v && typeof v === 'object') ? String(v.name || '') : String(v || '');
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const items = name => { try { return $(name).all().map(i => i.json).filter(j => j && j.id); } catch (e) { return []; } };

// Clients: id -> name, and the PlusVibe workspace the Run series is read from.
const clientName = {}; const clientWs = {};
for (const j of items('Get Clients')) { const f = j.fields || j; clientName[j.id] = String(f['Client'] || j.id); clientWs[j.id] = String(f['PlusVibe Workspace ID'] || '').trim(); }

// The syncs are the manager's eyes, and it ran them itself a moment ago. One of them dead (the Note
// nodes set sd.abort) means the numbers are stale, and the whole run stops here: no Stage move, no
// feed, one message saying why. A Failed run row is the record.
if (sd.abort) { sd.results = []; sd.updates = []; sd.managed = 0; sd.unmanaged = 0; sd.scope = 'aborted'; return [{ json: { _none: true } }]; }

// Every campaign that is not DRAFT or STOPPED, scoped by the client filter on a launched run.
// A campaign with a Stage is managed; Killed is out of the report; a campaign without a Stage is
// unmanaged and shown as such, so the board is complete and every gap is one decision away.
const camps = []; const unmanaged = [];
for (const j of items('Get Campaigns')) {
  const f = j.fields || j;
  const clientIds = (Array.isArray(f['Client']) ? f['Client'] : []).map(c => (c && typeof c === 'object') ? String(c.id || '') : String(c || '')).filter(Boolean);
  if (cf && !clientIds.includes(cf)) continue;
  const stage = nm(f['Stage']);
  if (stage === 'Killed') continue;
  const channel = nm(f['Channel']);
  const c = {
    rid: j.id,
    name: String(f['Campaign'] || j.id),
    campaignId: String(f['Campaign ID'] || '').trim(),
    sender: nm(f['Sequencer']) || '?',
    lane: channel === 'Email' ? 'Email' : 'LinkedIn',
    status: nm(f['Status']),
    stage,
    table: nm(f['Table']) || 'People',
    leads: num(f['Leads']),
    contacted: num(f['Contacted']),
    positives: num(f['Positive Replies (PV)']),
    liveView: String(f['Live View ID'] || '').trim(),
    clientId: clientIds[0] || '',
    lastSent: f['Last Sent'] || '',
    // Feeding state, written on this row by the deploy door at the end of every run.
    leftInView: (f['Left in View'] === undefined || f['Left in View'] === null || f['Left in View'] === '') ? null : num(f['Left in View']),
    lastFed: f['Last Fed'] || '',
  };
  // Without a Stage every campaign that ever sent is a decision, COMPLETED included: a finished one
  // may still want another run, and finished-for-good is spelled Killed, not blank.
  if (stage) camps.push(c); else if (c.clientId) unmanaged.push(c);
}
sd.scope = cf ? ((camps.length || unmanaged.length) ? 'one client (on demand)' : 'client filter matched no campaign') : 'all clients';
sd.managed = camps.length;
sd.unmanaged = unmanaged.length;

// Shared views: two in-play campaigns drinking from one Live View ID.
const inPlay = c => STANDARD.inPlayStages.includes(c.stage) && !STANDARD.notInPlayStatus.includes(c.status);
const viewUse = {};
for (const c of camps) if (inPlay(c) && c.liveView) viewUse[c.liveView] = (viewUse[c.liveView] || 0) + 1;

const byClient = {};
const updates = [];
const bucket = c => { const key = c.clientId || '(no client)'; return byClient[key] || (byClient[key] = { clientRecId: c.clientId, client: clientName[c.clientId] || (c.clientId ? c.clientId : '(no client)'), pvWorkspace: clientWs[c.clientId] || '', testProgress: [], testReady: [], scaleProgress: [], scaleReady: [], run: [], paused: [], unmanaged: [], fed: [], moved: [], failed: [] }); };
for (const c of unmanaged) { c.perPositive = c.positives ? Math.round(c.contacted / c.positives) : null; c.tags = []; bucket(c).unmanaged.push(c); }
for (const c of camps) {
  const R = bucket(c);
  c.perPositive = c.positives ? Math.round(c.contacted / c.positives) : null;
  c.tags = [];
  if (!inPlay(c)) {
    if (c.status === 'PAUSED') R.paused.push(c);
    continue;
  }
  if (!c.liveView) c.tags.push('NO VIEW');
  else if (viewUse[c.liveView] > 1) c.tags.push('SHARED VIEW');
  if (c.leftInView === 0) c.tags.push('DRY since ' + String(c.lastFed).slice(0, 10));
  if (c.lane === 'LinkedIn') c.tags.push('LINKEDIN');
  const need = STANDARD.positives[c.lane];
  // At the line: the stage total contacted, or the stage total held and the sender finished with it.
  // Status is the Hub's own vocabulary, every sync maps its sender into it, so this reads no platform.
  const atLine = stage => c.contacted >= STANDARD.line[stage] || (c.leads >= STANDARD.stageTotal[stage] && c.status === 'COMPLETED');
  if (c.stage === 'Test') {
    if (atLine('Test')) {
      if (c.positives >= need) { c.verdict = 'moved to Scale'; updates.push({ id: c.rid, Stage: 'Scale', name: c.name, client: R.client }); }
      else { c.verdict = 'killed'; updates.push({ id: c.rid, Stage: 'Killed', name: c.name, client: R.client }); }
      R.testReady.push(c); R.moved.push(c);
    } else R.testProgress.push(c);
  } else if (c.stage === 'Scale') {
    if (atLine('Scale')) R.scaleReady.push(c); else R.scaleProgress.push(c);
  } else R.run.push(c);
}
for (const k of Object.keys(byClient)) byClient[k].scaleReady.sort((a, b) => (a.perPositive || 1e9) - (b.perPositive || 1e9));
sd.results = Object.keys(byClient).map(k => byClient[k]).sort((a, b) => a.client.localeCompare(b.client));
sd.updates = updates;
sd.standard = STANDARD;
if (!updates.length) return [{ json: { _none: true } }];
return updates.map(u => ({ json: { id: u.id, Stage: u.Stage } }));

// Collect Updates: the Stage writes came back; a failed write is an error on the run, named by
// campaign, and the report still says what the standard decided. Emits one item so the chain
// continues into the messages whether there were updates or none.
const sd = $getWorkflowStaticData('global');
const updates = sd.updates || [];
let results = [];
try { results = $('Update Stage').all().map(i => i.json || {}); } catch (e) {}
sd.updated = 0;
updates.forEach((u, i) => {
  const r = results[i] || {};
  if (r.error || (r.id && r.id !== u.id)) sd.failed.push(u.client + ': could not set Stage ' + u.Stage + ' on "' + u.name + '": ' + JSON.stringify(r.error || r).slice(0, 160));
  else sd.updated++;
});
return [{ json: { updated: sd.updated, planned: updates.length } }];

// Build Messages: one Slack message per client. Stage headings as Slack text, each phase as its
// own monospace block kept under 80 columns so the client does not wrap it, every phase shown
// even when empty. A Run campaign gets its own small block: the all-time line, then the last
// weeks, so a stall reads as a falling column.
const sd = $getWorkflowStaticData('global');
const CHANNEL = 'C0B8Q745KT8'; // #flowroots-campaigns
const S = sd.standard || { line: { Test: 1000, Scale: 3000 } };
const fmt = v => Number(v || 0).toLocaleString('en-US');
const pad = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s.padEnd(n); };
const rpad = (s, n) => String(s == null ? '' : s).padStart(n);
// "2026-08-24 - US DTC - Agent Demo - pitch-led" reads as "US DTC, Agent Demo, pitch-led".
const title = c => String(c.name || '').replace(/^\d{4}-\d{2}-\d{2}\s*-\s*/, '').split(/\s+-\s+/).join(', ');
const tagText = c => (c.tags || []).filter(t => t !== 'LINKEDIN').map(t => t.replace(/^DRY since (\d{4})-(\d{2})-(\d{2})$/, (m, y, mo, d) => 'DRY ' + d + '/' + mo)).join(' · ');
const rate = c => c.perPositive ? '1 per ' + fmt(c.perPositive) : '';
// One campaign is one card: its name in bold as Slack text with its tag beside it, then its own
// block. In progress and paused: one line of numbers. Run: the all-time row and the last weeks,
// row under row. Scale ready is a comparison, so it is one block for the whole phase, ranked.
const pos = c => c.positives === 1 ? '1 positive' : fmt(c.positives) + ' positives';
const chips = (c, tail) => [tagText(c) ? '`' + tagText(c).split(' · ').join('`  `') + '`' : '', tail ? '`' + tail + '`' : ''].filter(Boolean).join('  ');
const heading = (c, tail) => '*' + title(c) + '*' + (chips(c, tail) ? '   ' + chips(c, tail) : '');
const block = rows => '```\n' + rows.join('\n') + '\n```';
const numsLine = (c, over) => [fmt(c.contacted) + (over ? ' of ' + fmt(over) : '') + ' contacted', pos(c)].concat(c.perPositive ? ['1 per ' + fmt(c.perPositive)] : []).join('     ');
const card = (c, over, tail) => [heading(c, tail), block([numsLine(c, over)])].join('\n');
const runRow = (label, contacted, positives) => pad(label, 10) + rpad(fmt(contacted), 7) + ' contacted' + rpad(fmt(positives), 6) + (positives === 1 ? ' positive ' : ' positives') + (positives ? '     1 per ' + fmt(Math.round(contacted / positives)) : '');
const runCard = c => {
  const rows = [runRow('all time', c.contacted, c.positives)];
  if (c.weeks && c.weeks.length) for (const w of c.weeks) rows.push(runRow(w.label, w.contacted, w.positives));
  else rows.push('(no weekly series from this sender)');
  return [heading(c), block(rows)].join('\n');
};
// Scale ready: one block, best first, so the ranking reads as a table.
const rankedBlock = list => block(list.map((c, i) => rpad(String(i + 1) + '.', 3) + ' ' + pad(title(c), 42) + rpad('1 per ' + (c.perPositive ? fmt(c.perPositive) : 'none'), 14) + rpad(fmt(c.contacted) + ' contacted', 18) + rpad(pos(c), 14)));
const phase = (label, cards) => cards.length ? ['_' + label + '_', ''].concat(cards.map(x => x + '\n')) : ['_' + label + ':_ none'];

const today = new Date().toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Asia/Jerusalem' });
const out = [];
// A stale sync stops everything: one message, no board, so nobody reads yesterday's numbers as today's.
if (sd.abort) { sd.messages = 1; return [{ json: { channel: CHANNEL, text: ':red_circle: *CAMPAIGNS MANAGER DID NOT RUN*  ·  ' + today + '\n' + sd.abort + '\nNo Stage moved, nothing fed, no board today.', client: '' } }]; }
for (const R of sd.results || []) {
  const inPlay = R.testProgress.length + R.testReady.length + R.scaleProgress.length + R.scaleReady.length + R.run.length;
  if (!inPlay && !R.paused.length && !R.unmanaged.length) continue;
  for (const c of R.fed || []) if (!c.tags.includes('FED')) c.tags.push('FED');
  // A dot in a client name reads as a link to Slack; a word joiner after it keeps the name plain.
  const parts = ['*' + R.client.toUpperCase().replace(/\./g, '.⁠') + '*  ·  ' + today + '  ·  ' + inPlay + ' in play  ·  ' + (R.fed || []).length + ' fed today'];
  parts.push('', ':test_tube: *TEST*');
  parts.push(...phase('in progress', R.testProgress.map(c => card(c, S.line.Test))));
  parts.push(...phase('ready', R.testReady.map(c => card(c, null, c.verdict === 'killed' ? 'KILLED' : 'MOVED TO SCALE'))));
  parts.push('', ':rocket: *SCALE*');
  parts.push(...phase('in progress', R.scaleProgress.map(c => card(c, S.line.Scale))));
  parts.push(...(R.scaleReady.length ? ['_ready, best first: Run or Killed_', rankedBlock(R.scaleReady)] : ['_ready:_ none']));
  parts.push('', ':large_green_circle: *RUN*', '');
  parts.push(...(R.run.length ? R.run.map(c => runCard(c) + '\n') : ['_none_']));
  parts.push('', ':double_vertical_bar: *PAUSED BY HAND*', '');
  parts.push(...(R.paused.length ? R.paused.map(c => card(c, null, 'set Killed or unpause') + '\n') : ['_none_']));
  if (R.unmanaged.length) {
    // One line each: the board is for decisions, and a campaign without a Stage is one decision,
    // Test, Scale, Run or Killed. The numbers ride along so it can be made from the line.
    parts.push('', ':white_circle: *NO STAGE*  ·  ' + R.unmanaged.length, '_set Test, Scale, Run or Killed on each_', '');
    parts.push(block(R.unmanaged.map(c => pad(title(c), 44) + pad(c.status.toLowerCase(), 10) + rpad(fmt(c.contacted), 6) + ' contacted' + rpad(fmt(c.positives), 4) + ' pos' + (c.perPositive ? rpad('1 per ' + fmt(c.perPositive), 13) : ''))));
  }
  out.push({ json: { channel: CHANNEL, text: parts.join('\n').replace(/\n{3,}/g, '\n\n'), client: R.client } });
}
sd.messages = out.length;
if (!out.length) return [{ json: { _none: true } }];
return out;

// Build Run Log: the run's one Hub row. Status computed from failed[], skips separate, the
// Description a human reads at a glance: scope, per client what is in play and what moved.
const sd = $getWorkflowStaticData('global');
const launch = sd.launch || {};
const results = sd.results || [];
const failed = (sd.failed || []).slice();
const updates = sd.updates || [];

let posted = 0;
try {
  for (const it of $('Post to Slack').all()) { const j = it.json || {}; if (j._none) continue; if (j.error) failed.push('Slack post failed: ' + JSON.stringify(j.error).slice(0, 160)); else if (j.ok || j.ts || j.message) posted++; }
} catch (e) {}

const lines = results.map(R => {
  const inPlay = R.testProgress.length + R.testReady.length + R.scaleProgress.length + R.scaleReady.length + R.run.length;
  const moved = R.moved.map(c => '"' + c.name + '" ' + c.verdict).join(', ');
  const dry = [].concat(R.testProgress, R.scaleProgress, R.run).filter(c => (c.tags || []).some(t => t.indexOf('DRY') === 0 || t === 'NO VIEW' || t === 'SHARED VIEW')).map(c => '"' + c.name + '" ' + c.tags.filter(t => t !== 'LINKEDIN').join(', ')).join('; ');
  const fed = (R.fed || []).map(c => '"' + c.name + '"').join(', ');
  return '- **' + R.client + ':** ' + inPlay + ' in play (Test ' + (R.testProgress.length + R.testReady.length) + ', Scale ' + (R.scaleProgress.length + R.scaleReady.length) + ', Run ' + R.run.length + '), ' + R.scaleReady.length + ' ready to judge, ' + R.paused.length + ' paused by hand, ' + (R.unmanaged || []).length + ' without a Stage' + (moved ? '. Moved: ' + moved : '') + (fed ? '. Fed: ' + fed : '') + (dry ? '. Flags: ' + dry : '');
});

// The syncs ran inside this run, first; their outcome is this row's, one line each.
const nf = v => Number(v || 0).toLocaleString('en-US');
const syncLines = (sd.syncs || []).map(s => s.ok
  ? '- **' + s.sync + ':** ' + (s.detail ? s.detail : nf(s.clients) + ' client(s), ' + nf(s.in) + ' campaign(s) seen, ' + nf(s.out) + ' written' + (s.threadsChecked ? ', ' + nf(s.threadsChecked) + ' thread(s) checked, ' + nf(s.threadsUpdated) + ' refreshed' : '')) + ', ' + (s.problems || []).length + ' problem(s), ' + nf(s.seconds) + ' s' + ((s.skips || []).length ? '. Skipped: ' + s.skips.join('; ') : '')
  : '- **' + s.sync + ':** FAILED, ' + s.why);

const parts = [
  '**' + (sd.managed || 0) + ' managed campaign(s) across ' + results.length + ' client(s), ' + (sd.updated || 0) + ' stage move(s), ' + (sd.fed || 0) + ' deploy row(s) created, ' + posted + ' message(s) posted**',
  '**Scope:** ' + (sd.scope || 'all clients') + '; ' + (sd.unmanaged || 0) + ' campaign(s) without a Stage shown as NO STAGE',
  '**Syncs:** ' + (sd.syncs || []).filter(s => s.ok).length + ' of ' + (sd.syncs || []).length + ' finished',
].concat(syncLines, ['**Slack:** ' + (posted ? posted + ' message(s) to #flowroots-campaigns' : 'nothing posted')], lines);
if (!results.length) parts.push('**Skipped (1, ' + (launch.clientFilter ? 'client filter matched no managed campaign' : 'no campaign carries a Stage') + ')**');
if (failed.length) parts.push('', '**Errors**', ...failed.map(f => '- ' + f));

const row = {
  'Automation': 'Campaigns Manager',
  'Status': sd.abort ? 'Failed' : (failed.length ? 'Succeeded with errors' : 'Succeeded'),
  'Run at': $now.toISO(),
  'Records In': sd.managed || 0,
  'Records Out': (sd.updated || 0) + (sd.fed || 0),
  'Errors': failed.length,
  'Target': 'Campaigns',
  'Trigger': launch.trigger || 'schedule',
  'Execution ID': String($execution.id),
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Duration s': Math.round(($now.toMillis() - (launch.startedAt || $now.toMillis())) / 1000),
  'Description': parts.join('\n'),
};
// Client is attached only when the run served exactly one client; never an empty link array.
if (launch.clientFilter) row['Client'] = [launch.clientFilter];
return [{ json: row }];

// Prep Run Stats: the Run block shows the last weeks beside the all-time line, so a stall reads
// as a falling column. PlusVibe answers totals over a date range per campaign
// (GET analytics/campaign/stats), so one call per week per Run campaign, Monday to Sunday,
// the last five weeks including the current one. A Run campaign on a sender without date
// stats keeps its all-time line only. No campaign, one placeholder so the chain reaches the
// messages.
const sd = $getWorkflowStaticData('global');
const WEEKS = 5;
const iso = d => d.toISOString().slice(0, 10);
const monday = d => { const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())); const day = t.getUTCDay() || 7; t.setUTCDate(t.getUTCDate() - day + 1); return t; };
const isoWeek = d => { const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())); const day = t.getUTCDay() || 7; t.setUTCDate(t.getUTCDate() + 4 - day); const y0 = new Date(Date.UTC(t.getUTCFullYear(), 0, 1)); return 'w' + String(Math.ceil((((t - y0) / 86400000) + 1) / 7)).padStart(2, '0'); };
const now = new Date();
const weeks = [];
for (let i = WEEKS - 1; i >= 0; i--) {
  const start = monday(new Date(now.getTime() - i * 7 * 86400000));
  const end = new Date(Math.min(start.getTime() + 6 * 86400000, now.getTime()));
  weeks.push({ label: isoWeek(start), start: iso(start), end: iso(end) });
}
const calls = [];
for (const R of sd.results || []) {
  for (const c of R.run) {
    if (c.sender !== 'PlusVibe' || !R.pvWorkspace || !c.campaignId) continue;
    for (const w of weeks) calls.push({ rid: c.rid, label: w.label, url: 'https://api.plusvibe.ai/api/v1/analytics/campaign/stats?workspace_id=' + encodeURIComponent(R.pvWorkspace) + '&campaign_id=' + encodeURIComponent(c.campaignId) + '&start_date=' + w.start + '&end_date=' + w.end });
  }
}
sd.runStatCalls = calls;
if (!calls.length) return [{ json: { _none: true } }];
return calls.map(x => ({ json: x }));

// Collect Run Stats: one answer per (campaign, week), in the order the calls went out. The
// answer is the campaign's totals over that range; new_lead_contacted_count is the people first
// contacted in the range, positive_reply_count the positives in it. A failed call leaves that
// week out and adds an error to the run; the report never hides a missing week behind a zero.
const sd = $getWorkflowStaticData('global');
const calls = sd.runStatCalls || [];
let res = [];
try { res = $('Run Stats').all().map(i => i.json || {}); } catch (e) {}
const byRid = {};
for (const R of sd.results || []) for (const c of R.run) byRid[c.rid] = { c, R };
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
calls.forEach((call, i) => {
  const hit = byRid[call.rid]; if (!hit) return;
  const j = res[i] || {};
  const body = Object.prototype.hasOwnProperty.call(j, 'body') ? j.body : j;
  const status = Number(j.statusCode || 0);
  // The body is the campaign objects indexed numerically, as an array or as an object of keys.
  let list = [];
  if (Array.isArray(body)) list = body;
  else if (body && typeof body === 'object') list = Object.keys(body).filter(k => /^\d+$/.test(k)).map(k => body[k]).concat(Array.isArray(body.data) ? body.data : []);
  const stat = list.find(x => x && String(x._id || x.id || '') === hit.c.campaignId) || (list.length === 1 ? list[0] : null);
  if ((status && (status < 200 || status >= 300)) || !stat) { sd.failed.push(hit.R.client + ': no ' + call.label + ' series for "' + hit.c.name + '" (status ' + (status || '?') + ')'); return; }
  hit.c.weeks = hit.c.weeks || [];
  hit.c.weeks.push({ label: call.label, contacted: num(stat.new_lead_contacted_count), positives: num(stat.positive_reply_count) });
});
return [{ json: { series: calls.length } }];

// Plan Feed: the standard's Feeding rule (standards/campaigns.md), applied after today's Stage
// moves. Every campaign in play with a Live View ID gets one deploy row on the Hub Automations
// table, which fires that sender's deploy door exactly as a hand-launched row does. No Max Rows:
// the deploy caps the run from the Stage. A campaign killed today is not fed; a campaign that
// already has a deploy row dated today is not fed twice, so a rerun is safe. The rows are the
// launch rows themselves; the doors write the outcome onto them.
const PLAN = { 'PlusVibe': { automation: 'Deploy View to PlusVibe Campaign', dedupe: 'Active-only' }, 'Alta': { automation: 'Deploy View to Alta Campaign' }, 'Email Bison': { automation: 'Deploy View to Email Bison Campaign' } };
const sd = $getWorkflowStaticData('global');
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Jerusalem' });
const feeds = [];
if (sd.abort) { sd.feeds = []; return [{ json: { _none: true } }]; }
for (const R of sd.results || []) {
  const inPlay = [].concat(R.testProgress, R.scaleProgress, R.run, R.testReady.filter(c => c.verdict !== 'killed'));
  for (const c of inPlay) {
    if (!c.liveView) continue;
    const plan = PLAN[c.sender];
    if (!plan) { sd.failed.push(R.client + ': "' + c.name + '" is on ' + c.sender + ', which has no deploy door; not fed'); continue; }
    if (!c.campaignId) { sd.failed.push(R.client + ': "' + c.name + '" has no Campaign ID; not fed'); continue; }
    const fedOn = c.lastFed ? new Date(c.lastFed).toLocaleDateString('en-CA', { timeZone: 'Asia/Jerusalem' }) : '';
    if (fedOn === today) { c.tags.push('FED TODAY'); continue; }
    const row = { 'Automation': plan.automation, 'Table': c.table || 'People', 'View': c.liveView, 'Target': c.campaignId, 'Trigger': 'schedule' };
    if (plan.dedupe) row['Dedupe Mode'] = plan.dedupe;
    if (c.clientId) row['Client'] = [c.clientId];
    feeds.push({ rid: c.rid, client: R.client, name: c.name, row });
    R.fed.push(c);
  }
}
sd.feeds = feeds;
if (!feeds.length) return [{ json: { _none: true } }];
return feeds.map(f => ({ json: f.row }));

// Collect Feeds: the deploy rows were created one per loop pass, four minutes apart, so each pass
// is its own run of Create Deploy Row and is read by run index. A row that failed to create is an
// error on the run, named by campaign; the campaign loses its FED tag so the report does not claim
// a feed that did not happen. Emits one item so the chain continues.
const sd = $getWorkflowStaticData('global');
const feeds = sd.feeds || [];
sd.fed = 0;
feeds.forEach((f, i) => {
  let r = {};
  try { const out = $('Create Deploy Row').all(0, i); r = (out[0] && out[0].json) || {}; } catch (e) { r = { error: 'no output for feed ' + (i + 1) }; }
  if (r.error || !r.id) {
    sd.failed.push(f.client + ': could not create the deploy row for "' + f.name + '": ' + JSON.stringify(r.error || r).slice(0, 160));
    for (const R of sd.results || []) R.fed = (R.fed || []).filter(c => c.rid !== f.rid);
  } else sd.fed++;
});
return [{ json: { fed: sd.fed, planned: feeds.length } }];

// Note PlusVibe Sync: the sync ran as a sub-workflow and handed back its summary, or died and the
// item carries the error. A dead sync means the numbers are stale, and the whole run stops at
// Decide: no Stage move, no feed, one red message, a Failed row that names it. A sync that finished
// with problems is fresh enough to run on; its problems land in this run's Errors.
const sd = $getWorkflowStaticData('global');
const SYNC = 'Sync PlusVibe Campaigns to Hub';
const j = ($input.first() || {}).json || {};
sd.syncs = sd.syncs || [];
if (j.error || !j._sync) {
  const why = j.error ? String(typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))).slice(0, 300) : 'returned no summary';
  sd.syncs.push({ sync: SYNC, ok: false, why });
  sd.failed.push(SYNC + ' failed: ' + why);
  if (!sd.abort) sd.abort = SYNC + ' failed: ' + why;
} else {
  sd.syncs.push(Object.assign({ sync: SYNC, ok: true }, j));
  for (const p of (j.problems || [])) sd.failed.push(SYNC + ': ' + p);
}
return [{ json: Object.assign({}, sd.launch) }];

