// Snapshot State: the feed loop ahead pauses between deploy rows, and a Wait node suspends the
// execution; workflow static data does not survive the resume, node output data does. So the run's
// whole state is parked here, in this node's output, and Restore State puts it back after the loop.
// Emits one item; Load Rows brings the deploy rows back from Plan Feed.
const sd = $getWorkflowStaticData('global');
const keep = ['launch', 'results', 'updates', 'feeds', 'failed', 'syncs', 'updated', 'fed', 'abort', 'managed', 'unmanaged', 'scope', 'standard', 'messages'];
const state = {};
for (const k of keep) if (sd[k] !== undefined) state[k] = JSON.parse(JSON.stringify(sd[k]));
return [{ json: { _state: state } }];

// Load Rows: the deploy rows Plan Feed built, one item each, for the feed loop. Nothing but the
// row's own columns rides an item: Create Deploy Row maps every key it sees onto the table.
return $('Plan Feed').all().filter(it => it.json && !it.json._none).map(it => ({ json: it.json }));

// Restore State: the feed loop is done and the execution resumed from its last wait with empty
// static data. Snapshot State parked the run's state in its output before the first wait; it
// comes back here so Collect Feeds, the board and the run row read the run they belong to.
const sd = $getWorkflowStaticData('global');
let state = {};
try { state = $('Snapshot State').first().json._state || {}; } catch (e) {}
for (const k of Object.keys(state)) sd[k] = state[k];
sd.failed = sd.failed || []; sd.results = sd.results || []; sd.feeds = sd.feeds || []; sd.syncs = sd.syncs || [];
return [{ json: { restored: Object.keys(state).length } }];
